<template><header class="vs-page-header"><nav v-if="breadcrumbs.length" aria-label="Đường dẫn"><ol><li v-for="(item,index) in breadcrumbs" :key="item.label"><router-link v-if="item.to&&index<breadcrumbs.length-1" :to="item.to">{{item.label}}</router-link><span v-else :aria-current="index===breadcrumbs.length-1?'page':undefined">{{item.label}}</span></li></ol></nav><div class="vs-page-header__main"><div><div v-if="$slots.context" class="vs-page-header__context"><slot name="context"/></div><div class="vs-page-header__title"><h1>{{title}}</h1><slot name="status"/></div><p v-if="description">{{description}}</p></div><div v-if="$slots.actions" class="vs-page-header__actions"><slot name="actions"/></div></div></header></template>
<script setup>defineProps({title:{type:String,required:true},description:{type:String,default:''},breadcrumbs:{type:Array,default:()=>[]}})</script>
<style scoped>.vs-page-header{display:grid;gap:var(--space-3);margin-bottom:var(--space-6)}ol{display:flex;align-items:center;flex-wrap:wrap;gap:var(--space-2);color:var(--text-muted);font-size:var(--type-caption-size)}li:not(:last-child)::after{content:'/';margin-left:var(--space-2);color:var(--text-disabled)}a{color:var(--text-link)}.vs-page-header__main{display:flex;align-items:flex-start;justify-content:space-between;gap:var(--space-6)}.vs-page-header__title{display:flex;align-items:center;flex-wrap:wrap;gap:var(--space-3)}h1{font-size:var(--type-h1-size);line-height:var(--type-h1-line);letter-spacing:-.02em}p{max-width:64ch;color:var(--text-secondary);font-size:var(--type-body-lg-size);line-height:var(--type-body-lg-line)}.vs-page-header__context{margin-bottom:var(--space-1);color:var(--text-muted);font-size:var(--type-caption-size);font-weight:700}.vs-page-header__actions{display:flex;flex-wrap:wrap;justify-content:flex-end;gap:var(--space-3)}@media(max-width:720px){.vs-page-header__main{display:grid}.vs-page-header__actions{justify-content:flex-start;width:100%}}</style>
